class Box
    public define content as integer;
endClass

algorithm TryIndependentCopy
    define mutable initialValue as integer <- 0;
    define mutable newValue as integer <- 0;
    read initialValue;
    read newValue;
    define original as Box <- new Box();
    original.content <- initialValue;
    define cloned as Box <- copy(original);
    cloned.content <- newValue;
    write original.content;
endAlgorithm
